import assert from 'node:assert/strict';
import { test } from 'vitest';
import { createGame } from './game.ts';
import { decodeSnapshot, encodeSnapshot, GAME_NAME_MAX_CHARACTERS } from './snapshot.ts';
import { EXAMPLE_CODE } from './game.fixture.ts';

test('named and legacy snapshots load regardless of property order', () => {
  const state = { ...createGame(EXAMPLE_CODE), name: '夜 ✨ game' };
  const named: unknown = JSON.parse(encodeSnapshot(state));
  assert.ok(named && typeof named === 'object');
  const reordered = Object.fromEntries(Object.entries(named).reverse());
  assert.deepEqual(decodeSnapshot(JSON.stringify(reordered)), state);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(createGame(EXAMPLE_CODE))), createGame(EXAMPLE_CODE));
  assert.equal(decodeSnapshot(JSON.stringify({ ...reordered, name: 42 })), null);
  assert.equal(
    decodeSnapshot(JSON.stringify({ ...reordered, name: 'x'.repeat(GAME_NAME_MAX_CHARACTERS + 1) })),
    null,
  );
  assert.equal(decodeSnapshot(JSON.stringify({ ...reordered, extra: true })), null);
  const { boardCode: _boardCode, ...missing } = reordered;
  assert.equal(decodeSnapshot(JSON.stringify(missing)), null);
});

/work/tests/snapshot-name.e2e.test.ts.content:
import { expect, test } from './browser-test.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { loadTimedBoard } from './game-fixture.ts';

test('a named game can be exported, loaded in a different order, and renamed', async ({ page }) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(0).click();
  await page.locator('summary').click();
  const name = page.getByLabel(ReproductionControl.name, { exact: true });
  const snapshot = page.getByLabel(ReproductionControl.snapshot, { exact: true });
  await name.fill('Evening ✨');
  await page.getByRole('button', { name: ReproductionControl.exportSnapshot, exact: true }).click();
  const saved = JSON.parse(await snapshot.inputValue());
  expect(saved.name).toBe('Evening ✨');
  await page.getByRole('button', { name: DealControl.newGame, exact: true }).click();
  await expect(name).toHaveValue('');
  await snapshot.fill(JSON.stringify(Object.fromEntries(Object.entries(saved).reverse())));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await expect(name).toHaveValue('Evening ✨');
  await expect(page.locator('.card.revealed')).toHaveCount(1);
  await expect(page.getByRole('button', { name: ReproductionControl.resume })).toBeVisible();
  await name.fill('Another name');
  await snapshot.fill('{');
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await expect(name).toHaveValue('Another name');
  await page.getByRole('button', { name: ReproductionControl.exportSnapshot, exact: true }).click();
  expect(JSON.parse(await snapshot.inputValue()).name).toBe('Another name');
});

